#[using="Type"] Lemma rdn_visible : forall (H : word -> bool) FULL (a : word) w bs,
  H_off_segments SEGS H ->
  rdn SEGS (mrestrict H FULL) a w = Some bs ->
  forall x : word, bv_unsigned a <= bv_unsigned x < bv_unsigned a + Z.of_nat w -> H x = false.
Proof.
