(* [comment removed for export] *)
#[using="Type"] Lemma list_set_nth_maps_match : forall E ms l i m sz,
  nth_error ms i = Some m -> is_fog m = false -> 0 <= sz < two64 ->
  bv_unsigned (edenot E (am_len m)) <= sz ->
