(* [comment removed for export] *)
#[using="Type"] Lemma hop_sub_replay : forall E b n eb en h,
  edenot E eb = edenot E b -> edenot E en = edenot E n ->
  hreplay E (map (hop_sub b n eb en) h) = hreplay E h.
Proof.
