  #[using="m Hfw Hbw ER"] Lemma hreplay_rename : forall E h,
    forallb (fun h0 => evars_all (ren_ok fw bw) (hop_b h0) && evars_all (ren_ok fw bw) (hop_n h0)) h = true ->
    hreplay (ren_env bw E) (map (hrename fw) h) = hreplay E h.
Proof.
